{
  "name": "whatsdoc-backend",
  "version": "1.0.0",
  "description": "Lightweight Node Backend",
  "main": "server.js",
  "type": "module",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "axios": "^1.6.0",
    "cors": "^2.8.5",
    "express": "^4.18.2",
    "mongoose": "^8.0.0",
    "multer": "^1.4.5-lts.1"
  }
}

import express from 'express';
import cors from 'cors';
import multer from 'multer';
import mongoose from 'mongoose';
import axios from 'axios';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// --- CONFIG ---
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PORT = process.env.PORT || 8000;
const MONGO_URI = process.env.MONGO_URI || 'mongodb://admin:secret123@mongo:27017';
const WAHA_API_URL = process.env.WAHA_API_URL || 'http://waha:3000';
const WAHA_API_KEY = process.env.WAHA_API_KEY || 'secret123';
const WAHA_SESSION = process.env.WAHA_WORKER_ID || 'default';

// --- APP SETUP ---
const app = express();
app.use(cors());
app.use(express.json());

// Ensure uploads directory exists
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) fs.mkdirSync(uploadDir);

// Configure Multer for File Uploads
const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, uploadDir)
  },
  filename: function (req, file, cb) {
    // Keep original filename to match videoName logic
    cb(null, file.originalname)
  }
});
const upload = multer({ storage: storage });

// --- DATABASE ---
mongoose.connect(MONGO_URI)
  .then(() => console.log('✅ MongoDB Connected'))
  .catch(err => console.error('❌ MongoDB Error:', err));

const CustomerSchema = new mongoose.Schema({
  customerName: String,
  phoneNumber: String,
  videoName: String,
  status: { type: String, default: 'pending' },
  error: String,
  requestedAt: { type: Date, default: Date.now },
  completedAt: Date
});

const Customer = mongoose.model('Customer', CustomerSchema);

// --- HELPERS ---
const formatPhone = (phone) => {
  const clean = phone.replace(/[^0-9]/g, '');
  return `${clean}@c.us`;
};

// --- ROUTES ---

// 1. Register Customer
app.post('/register-customer', async (req, res) => {
  try {
    const { name, phone, videoName } = req.body;
    if (!name || !phone || !videoName) return res.status(400).json({ error: 'Missing fields' });

    const newCustomer = new Customer({
      customerName: name,
      phoneNumber: phone,
      videoName: videoName
    });

    await newCustomer.save();
    res.json({ success: true, id: newCustomer._id });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// 2. Get Pending
app.get('/get-pending', async (req, res) => {
  try {
    const docs = await Customer.find({ status: 'pending' }).sort({ requestedAt: 1 }).limit(100);
    // Map to frontend interface
    const mapped = docs.map(d => ({
        id: d._id,
        customerName: d.customerName,
        phoneNumber: d.phoneNumber,
        videoName: d.videoName,
        status: d.status,
        requestedAt: d.requestedAt
    }));
    res.json(mapped);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// 3. Get Failed
app.get('/get-failed', async (req, res) => {
  try {
    const docs = await Customer.find({ status: 'failed' }).sort({ requestedAt: -1 }).limit(50);
    const mapped = docs.map(d => ({
        id: d._id,
        customerName: d.customerName,
        phoneNumber: d.phoneNumber,
        videoName: d.videoName,
        status: d.status,
        requestedAt: d.requestedAt,
        error: d.error
    }));
    res.json(mapped);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// 4. Upload & Send Logic
app.post('/upload-document', upload.single('file'), async (req, res) => {
  // Multer handles the file parsing BEFORE we get here, solving the 422 issue
  const { requestId, phoneNumber, videoName } = req.body;
  const file = req.file;

  if (!requestId || !file) {
    return res.status(400).json({ error: 'Missing file or ID' });
  }

  // Respond immediately to UI so it feels fast, handle logic in background
  res.json({ success: true, message: 'Processing' });

  // --- BACKGROUND PROCESS ---
  processUpload(requestId, phoneNumber, videoName, file).catch(err => {
    console.error(`Background Error [${requestId}]:`, err);
  });
});

// The core logic function
async function processUpload(requestId, phone, videoName, fileObj) {
  const filePath = fileObj.path;

  try {
    console.log(`Processing ${videoName} for ${phone}`);

    // 1. Prepare Base64
    const fileData = fs.readFileSync(filePath);
    const b64 = fileData.toString('base64');
    const mime = fileObj.mimetype;
    const dataUri = `data:${mime};base64,${b64}`;
    const chatId = formatPhone(phone);

    // 2. Send to WAHA
    const payload = {
      chatId: chatId,
      caption: `Hello! Here is your document: ${videoName}`,
      session: WAHA_SESSION,
      file: {
        mimetype: mime,
        filename: fileObj.originalname,
        data: dataUri
