async function processUpload(requestId, phone, videoName, fileObj) {
  const filePath = fileObj.path;

  try {
    // Format Phone: remove non-digits, add @c.us
    const cleanPhone = phone.replace(/[^0-9]/g, '');
    const chatId = `${cleanPhone}@c.us`;

    // Read file for WAHA
    const fileData = fs.readFileSync(filePath);
    const b64 = fileData.toString('base64');
    const mime = fileObj.mimetype;
    const dataUri = `data:${mime};base64,${b64}`;

    // WAHA Payload
    const payload = {
      chatId: chatId,
      caption: `Hello! Here is your document: ${videoName}`,
      session: WAHA_SESSION,
      file: {
        mimetype: mime,
        filename: fileObj.originalname,
        data: dataUri
      }
    };

    console.log(`🚀 Sending to WAHA (${WAHA_API_URL})...`);

    await axios.post(`${WAHA_API_URL}/api/sendFile`, payload, { 
        headers: { 
            'Content-Type': 'application/json',
            'X-Api-Key': WAHA_API_KEY 
        }
    });

    console.log("✅ Send Success");

    await Customer.findByIdAndUpdate(requestId, {
        status: 'completed',
        completedAt: new Date(),
        error: null
    });

  } catch (error) {
    const errMsg = error.response?.data ? JSON.stringify(error.response.data) : error.message;
    console.error(`❌ Send Failed: ${errMsg}`);

    await Customer.findByIdAndUpdate(requestId, {
        status: 'failed',
        error: errMsg
    });

  } finally {
      // Clean up disk
      if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  }
}

app.listen(PORT, '0.0.0.0', () => {
  console.log(`🚀 Node.js Backend listening on 0.0.0.0:${PORT}`);
});

